#!/usr/bin/env python3
"""Fetch raw order pages and customer records from the local order service.

usage: fetch.py orders    DATA_DIR
       fetch.py customers DATA_DIR IDS_FILE

Raw response bodies are saved under DATA_DIR/pages and DATA_DIR/customers so the
calculation can be done (and re-done) offline. Every non-200 response is logged
in full to DATA_DIR/events.log.
"""
import email.utils
import http.client
import json
import os
import socket
import sys
import time
import urllib.error
import urllib.request

BASE = "http://localhost:8080"
ORDER_KEYS = {"id", "customer_id", "status", "placed_at", "amount_cents"}
CUSTOMER_KEYS = {"id", "name", "region", "tier", "discount_pct"}
NET_ERRORS = (urllib.error.URLError, socket.timeout, ConnectionError, http.client.HTTPException, OSError)


class Unrecognised(Exception):
    pass


def wait_seconds(headers, body):
    """Return the wait the service asked for, in seconds, or None if it gave none we can read."""
    h = {k.lower(): v for k, v in headers.items()}
    if "retry-after" in h:
        value = h["retry-after"].strip()
        try:
            return float(value)
        except ValueError:
            when = email.utils.parsedate_to_datetime(value)
            return max(0.0, when.timestamp() - time.time())
    try:
        parsed = json.loads(body)
    except ValueError:
        return None
    if isinstance(parsed, dict):
        for key, value in parsed.items():
            k = key.lower()
            if ("retry" in k or "wait" in k) and isinstance(value, (int, float)) and not isinstance(value, bool):
                return value / 1000.0 if "ms" in k or "millis" in k else float(value)
    return None


class Service:
    def __init__(self, data_dir):
        self.data_dir = data_dir
        os.makedirs(os.path.join(data_dir, "pages"), exist_ok=True)
        os.makedirs(os.path.join(data_dir, "customers"), exist_ok=True)
        self.log_file = open(os.path.join(data_dir, "events.log"), "a")
        self.token = None
        self.fresh_token_401s = 0
        self.requests = 0
        self.tokens_issued = 0

    def log(self, msg):
        line = f"{time.strftime('%H:%M:%S')} req#{self.requests} {msg}"
        print(line, flush=True)
        self.log_file.write(line + "\n")
        self.log_file.flush()

    def raw(self, method, path, auth):
        headers = {}
        if auth:
            headers["Authorization"] = "Bearer " + self.token
        req = urllib.request.Request(
            BASE + path, method=method, headers=headers, data=b"" if method == "POST" else None
        )
        self.requests += 1
        try:
            with urllib.request.urlopen(req, timeout=20) as r:
                return r.status, dict(r.headers), r.read()
        except urllib.error.HTTPError as e:
            return e.code, dict(e.headers), e.read()

    def call(self, method, path, auth=True, accept_404=False):
        """One logical request: repeat through 401 / 429 / 5xx / network errors until it succeeds."""
        attempt = 0
        while True:
            attempt += 1
            if attempt > 80:
                raise Unrecognised(f"{method} {path}: gave up after {attempt - 1} attempts")
            if auth and self.token is None:
                self.issue_token()
            try:
                status, headers, body = self.raw(method, path, auth)
            except NET_ERRORS as e:
                self.log(f"NETERR {method} {path}: {e!r}")
                time.sleep(min(0.25 * 2 ** min(attempt, 5), 5))
                continue
            if status == 200:
                if auth:
                    self.fresh_token_401s = 0
                return status, headers, body
            self.log(f"HTTP {status} {method} {path} headers={headers} body={body[:400]!r}")
            if status == 404 and accept_404:
                return status, headers, body
            if status == 401 and auth:
                # token expired (or rejected): fetch a fresh one and repeat
                self.token = None
                self.fresh_token_401s += 1
                if self.fresh_token_401s > 3:
                    raise Unrecognised("401 on three consecutive fresh tokens")
                continue
            if status == 429:
                wait = wait_seconds(headers, body)
                if wait is None:
                    raise Unrecognised("429 with no wait time we can read; see log")
                self.log(f"rate limited: waiting {wait}s as instructed")
                time.sleep(wait)
                continue
            if status >= 500:
                time.sleep(min(0.25 * 2 ** min(attempt, 5), 5))
                continue
            raise Unrecognised(f"unexpected HTTP {status} for {method} {path}")

    def issue_token(self):
        status, headers, body = self.call("POST", "/token", auth=False)
        self.token = json.loads(body)["token"]
        self.tokens_issued += 1
        self.fresh_token_401s = 0 if False else self.fresh_token_401s  # counter reset only on success
        self.log(f"issued token #{self.tokens_issued}: {self.token}")

    # -- orders ---------------------------------------------------------------------------

    def fetch_page(self, page):
        path = f"/orders?page={page}"
        for attempt in range(1, 6):
            status, headers, body = self.call("GET", path)
            try:
                data = json.loads(body)
                problem = self.check_page(data, page)
            except ValueError as e:
                data, problem = None, f"not valid JSON: {e}"
            if problem is None:
                with open(os.path.join(self.data_dir, "pages", f"page-{page:03d}.json"), "wb") as f:
                    f.write(body)
                return data
            self.log(f"INVALID page {page} (attempt {attempt}): {problem}; body[:200]={body[:200]!r}")
            time.sleep(0.5)
        raise Unrecognised(f"page {page} stayed invalid")

    @staticmethod
    def check_page(data, page):
        if not isinstance(data, dict):
            return "top level is not an object"
        for key in ("page", "total_pages", "items", "next"):
            if key not in data:
                return f"missing key {key}"
        if data["page"] != page:
            return f"page field is {data['page']!r}, asked for {page}"
        if not isinstance(data["items"], list):
            return "items is not a list"
        for item in data["items"]:
            if not isinstance(item, dict) or set(item) != ORDER_KEYS:
                return f"item with unexpected shape: {item!r}"
        return None

    def fetch_orders(self):
        page, total_pages, fetched = 1, None, []
        while True:
            data = self.fetch_page(page)
            fetched.append(page)
            if total_pages is None:
                total_pages = data["total_pages"]
            elif data["total_pages"] != total_pages:
                self.log(f"NOTE total_pages changed {total_pages} -> {data['total_pages']} on page {page}")
                total_pages = data["total_pages"]
            expected_next = f"/orders?page={page + 1}" if page < total_pages else None
            self.log(f"page {page}/{total_pages}: {len(data['items'])} items, next={data['next']!r}")
            if data["next"] != expected_next:
                self.log(f"NOTE next={data['next']!r} but expected {expected_next!r}")
            if data["next"] is None:
                break
            page = int(data["next"].split("page=")[1])
        missing = [p for p in range(1, total_pages + 1) if p not in fetched]
        for p in missing:
            self.log(f"NOTE page {p} was not reached through 'next'; fetching it directly")
            self.fetch_page(p)
        self.log(f"orders done: pages fetched={len(fetched) + len(missing)} total_pages={total_pages}")

    # -- customers ------------------------------------------------------------------------

    def fetch_customer(self, cid):
        ok_path = os.path.join(self.data_dir, "customers", f"{cid}.json")
        missing_path = os.path.join(self.data_dir, "customers", f"{cid}.404")
        if os.path.exists(ok_path) or os.path.exists(missing_path):
            return
        for attempt in range(1, 6):
            status, headers, body = self.call("GET", f"/customers/{cid}", accept_404=True)
            if status == 404:
                with open(missing_path, "wb") as f:
                    f.write(body)
                self.log(f"customer {cid}: 404 {body[:200]!r}")
                return
            try:
                data = json.loads(body)
            except ValueError:
                data = None
            if isinstance(data, dict) and set(data) == CUSTOMER_KEYS and data["id"] == cid:
                with open(ok_path, "wb") as f:
                    f.write(body)
                return
            self.log(f"INVALID customer {cid} (attempt {attempt}): body[:200]={body[:200]!r}")
            time.sleep(0.5)
        raise Unrecognised(f"customer {cid} stayed invalid")

    def fetch_customers(self, ids):
        for n, cid in enumerate(ids, 1):
            self.fetch_customer(cid)
        self.log(f"customers done: {len(ids)} ids")


def main(argv):
    mode, data_dir = argv[1], argv[2]
    svc = Service(data_dir)
    if mode == "orders":
        svc.fetch_orders()
    elif mode == "customers":
        with open(argv[3]) as f:
            ids = [line.strip() for line in f if line.strip()]
        svc.fetch_customers(ids)
    else:
        raise SystemExit(__doc__)
    svc.log(f"finished: {svc.requests} requests, {svc.tokens_issued} tokens issued")


if __name__ == "__main__":
    main(sys.argv)

