                with open(ok_path, "wb") as f:
                    f.write(body)
                return
            self.log(f"INVALID customer {cid} (attempt {attempt}): body[:200]={body[:200]!r}")
            time.sleep(0.5)
        raise Unrecognised(f"customer {cid} stayed invalid")

    def fetch_customers(self, ids):
